package everlongcvamm

import (
	"encoding/csv"
	"os"
	"testing"

	"github.com/holiman/uint256"
	"github.com/stretchr/testify/require"
)

// fixtureCase is one row of testdata/cvamm_fixtures.csv — ground truth generated by a
// forge script (blockend @ feat/virtual-ladder-curve) running the shipped-semantics
// (via_ir-pinned) CvammCurve library over a grid of supports, anchors, scales,
// coordinates, directions and trade sizes, including band-edge truncation and
// below-resolution dust. Independently cross-checked wei-exact against the hummingbot
// Python replica (itself on-chain-fuzz-verified).
type fixtureCase struct {
	sup                    Support
	anchor, kappa, x       *uint256.Int
	stableIn               bool
	amountIn               *uint256.Int
	gross, xAfter, unspent *uint256.Int
}

type yCase struct {
	a, x, y *uint256.Int
}

func loadFixtures(t *testing.T) ([]fixtureCase, []yCase) {
	t.Helper()
	f, err := os.Open("testdata/cvamm_fixtures.csv")
	require.NoError(t, err)
	defer f.Close()

	rows, err := csv.NewReader(f).ReadAll()
	require.NoError(t, err)
	require.Greater(t, len(rows), 1)

	u := func(s string) *uint256.Int {
		v, err := uint256.FromDecimal(s)
		require.NoError(t, err)
		return v
	}

	var swaps []fixtureCase
	var ys []yCase
	for _, row := range rows[1:] {
		switch row[0] {
		case "Y":
			ys = append(ys, yCase{a: u(row[1]), x: u(row[7]), y: u(row[10])})
		case "S":
			swaps = append(swaps, fixtureCase{
				sup:      Support{AWad: u(row[1]), XLo: u(row[2]), XHi: u(row[3]), YHi: u(row[4])},
				anchor:   u(row[5]),
				kappa:    u(row[6]),
				x:        u(row[7]),
				stableIn: row[8] == "1",
				amountIn: u(row[9]),
				gross:    u(row[10]),
				xAfter:   u(row[11]),
				unspent:  u(row[12]),
			})
		}
	}
	return swaps, ys
}

func TestYAtXParity(t *testing.T) {
	_, ys := loadFixtures(t)
	require.NotEmpty(t, ys)
	for _, c := range ys {
		var y uint256.Int
		require.NoError(t, yAtX(&y, c.x, c.a))
		require.Equal(t, c.y.Dec(), y.Dec(), "yAtX(%s, %s)", c.x.Dec(), c.a.Dec())
	}
}

func TestSwapExactInX96Parity(t *testing.T) {
	swaps, _ := loadFixtures(t)
	require.NotEmpty(t, swaps)
	for i, c := range swaps {
		var gross, xAfter, unspent uint256.Int
		err := swapExactInX96(&gross, &xAfter, &unspent, &c.sup, c.anchor, c.kappa, c.x,
			c.stableIn, c.amountIn)
		require.NoError(t, err, "case %d", i)
		require.Equal(t, c.gross.Dec(), gross.Dec(), "case %d gross", i)
		require.Equal(t, c.xAfter.Dec(), xAfter.Dec(), "case %d xAfter", i)
		require.Equal(t, c.unspent.Dec(), unspent.Dec(), "case %d unspent", i)
	}
}

func TestYAtXDomainAndAmplification(t *testing.T) {
	var y uint256.Int
	a := uint256.NewInt(1).Mul(uint256.NewInt(22), uWad)

	require.ErrorIs(t, yAtX(&y, uint256.NewInt(1e15-1), a), ErrCurveDomain)
	require.ErrorIs(t, yAtX(&y, uint256.NewInt(1999e15+1), a), ErrCurveDomain)
	require.NoError(t, yAtX(&y, uint256.NewInt(1e15), a))
	require.NoError(t, yAtX(&y, uint256.NewInt(1999e15), a))

	x := uint256.NewInt(5e17)
	require.ErrorIs(t, yAtX(&y, x, uint256.NewInt(5e17)), ErrCurveAmplification)
	require.NoError(t, yAtX(&y, x, uint256.NewInt(5e17+1)))
}

// TestZeroInputIsNoOp guards the contract's zero-input early return: without it the
// stable-in bisection would land on the leftmost coordinate of a floored-y tread and a
// zero input would move the coordinate.
func TestZeroInputIsNoOp(t *testing.T) {
	swaps, _ := loadFixtures(t)
	c := swaps[0]
	var gross, xAfter, unspent uint256.Int
	require.NoError(t, swapExactInX96(&gross, &xAfter, &unspent, &c.sup, c.anchor, c.kappa,
		c.x, true, uint256.NewInt(0)))
	require.True(t, gross.IsZero())
	require.Equal(t, c.x.Dec(), xAfter.Dec())
	require.True(t, unspent.IsZero())
}

func TestRetractedBookErrors(t *testing.T) {
	swaps, _ := loadFixtures(t)
	c := swaps[0]
	var gross, xAfter, unspent uint256.Int
	err := swapExactInX96(&gross, &xAfter, &unspent, &c.sup, uint256.NewInt(0), c.kappa,
		c.x, true, uint256.NewInt(1e18))
	require.ErrorIs(t, err, ErrRetractedBook)
	err = swapExactInX96(&gross, &xAfter, &unspent, &c.sup, c.anchor, uint256.NewInt(0),
		c.x, true, uint256.NewInt(1e18))
	require.ErrorIs(t, err, ErrRetractedBook)
}
